"""Partituren des Soundtracks. Melodie-Zeichen: Stufen der Tonleiter, 0 = Grundton, 1 = zweite Stufe … 7 = Oktave, Z, Y, X = Stufen darunter;
"." hält den Ton, "-" ist Pause. 16 Zeichen = ein Takt. Akkorde: Stufe je Takt (0 = Tonika). Bass: r Grundton, o Oktave, f Quinte, t Terz."""
THEMES = {}

def theme(name, **kw):
    THEMES[name] = kw

FOUR = dict(kick="x-------x-------", snare="----x-------x---", hat="x-x-x-x-x-x-x-x-")
BACK = dict(kick="x-----x---x-----", snare="----x-------x---", hat="x-x-x-x-x-x-xox-")

